INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64317361', 64317361, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Penyusunan Laporan Pertanggungjawaban dan Evaluasi Pengelolaan Sumber Dana Non-APBN pada Kegiatan Partisipasi Indonesia pada Expo 2025 Osaka', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 63000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1) Analisis dan Penyusunan Laporan Pertanggungjawaban: Melakukan analisis terhadap pelaksanaan pengelolaan sumber dana Non-APBN serta menyusun Laporan Pertanggungjawaban dan Evaluasi secara komprehensif dan sistematis, dengan mengacu pada ketentuan peraturan perundang-undangan yang berlaku, perjanjian kerja sama, dan prinsip tata kelola yang baik. 2) Konsolidasi, Verifikasi, dan Sinkronisasi Dokumen Pendukung: Melakukan konsolidasi dan verifikasi dokumen pendukung yang meliputi Perjanjian Kerja Sama (PKS) dengan para mitra dukungan kegiatan, Rincian Anggaran Biaya (RAB) alokasi dana Non-APBN, dokumen pembayaran dan bukti transaksi, berita acara, serta dokumen pelaporan lainnya, guna memastikan kesesuaian, konsistensi, dan keterkaitan antara perencanaan, realisasi, dan output kegiatan.', '3) Identifikasi Risiko dan Permasalahan Tata Kelola: Mengidentifikasi potensi risiko dan tata kelola dalam pengelolaan dana Non-APBN berdasarkan hasil analisis dokumen, serta menyusun catatan evaluatif sebagai bahan perbaikan dan aset acuan mekanisme pengelolaan dana Non-APBN untuk event internasional di masa depan. 4) Evaluasi Kesesuaian Pengelolaan Dana dengan Capaian Output Kegiatan: Melakukan evaluasi terhadap kesesuaian penggunaan dana Non-APBN dengan peruntukan dan tujuan kegiatan, termasuk analisis keterkaitan antara realisasi penggunaan dana dan capaian output kegiatan Partisipasi Indonesia pada Expo 2025 Osaka. 5) Penyusunan Rekomendasi/Lesson learned Perbaikan Tata Kelola: Menyusun rekomendasi berbasis hasil evaluasi dan analisis untuk peningkatan akuntabilitas, transparansi, dan efektivitas pengelolaan sumber dana Non-APBN pada kegiatan serupa di masa mendatang. 6) Penyusunan Laporan Kemajuan dan Laporan Akhir: Menyusun laporan kemajuan pekerjaan sesuai dengan termin yang telah ditetapkan selama masa kontrak berlangsung, serta laporan akhir yang memuat rangkuman kegiatan, hasil analisis dan evaluasi, serta dukungan yang telah diberikan dalam penyusunan laporan pertanggungjawaban.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 325237);
