INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64641463', 64641463, 'analyze_legacy', 'Kementerian Hukum', 'central', '03 BALAI HARTA PENINGGALAN SEMARANG', 'Pengadaan Belanja Modal Peralatan dan Mesin berupa Mesin Absensi Balai Harta Peninggalan Semarang Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 7300000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 unit', 'Pengadaan mesin absensi elektronik untuk mendukung pencatatan kehadiran pegawai secara akurat dan terintegrasi. Mesin absensi yang disediakan harus memiliki fitur identifikasi biometrik dan/atau kartu, kapasitas penyimpanan data yang memadai, serta mendukung pengelolaan dan rekapitulasi data kehadiran. Pekerjaan meliputi pengadaan unit, pengiriman, instalasi di lokasi yang ditentukan, pengujian fungsi hingga siap digunakan, serta penyerahan hasil pekerjaan yang dibuktikan dengan Berita Acara Serah Terima.', 'Mesin absensi elektronik dengan fitur identifikasi biometrik sidik jari dan pengenalan wajah, mendukung kartu RFID, memiliki kapasitas penyimpanan data dan pengguna yang memadai, layar warna, kamera terintegrasi, serta konektivitas LAN dan/atau Wi-Fi untuk pengelolaan data. Perangkat dalam kondisi baru (bukan rekondisi), dilengkapi adaptor dan perangkat lunak pendukung, termasuk pengiriman, instalasi, pengujian fungsi hingga siap digunakan, serta disertai garansi resmi pabrikan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 327706);
