INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62934368', 62934368, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'BIRO PENDIDIKAN DAN MENTAL SPIRITUAL', 'Fasilitasi Petugas Haji Daerah di Arab Saudi', 'Jasa Lainnya', 'Tender', 'DKI Jakarta, Jakarta Pusat (Kota)', 1128500000, 'February 2026', 'APBD', 1, 1, '1 paket', 'Belanja Makanan dan Minuman Rapat, Belanja Sewa Kendaraan Bermotor Penumpang, Belanja Sewa Hotel, Belanja Jasa Konsultansi Berorientasi Layanan-Jasa Khusus', '1. penyediaan transportasi kendaraan operasional dengan spesifikasi pekerjaan : Kendaraan keluaran minimal tahun 2020, Kondisi baik dan terawat, Kapasitas Mesin + 4000 CC, Kapasitas penumpang + 8 orang, termasuk sopir, bahan bakar dan uang parkir, sopir orang Indonesia yang bisa bahasa Arab dan memahami lokasi pemondokan jamaah haji Indonesia kantor Daker/Kantor kesehatan haji/ rumah sakit/sektor/ PPIH Arab Saudi, kendaraan operasional yang akan digunakan memiliki tasrih untuk digunakan di lokasi mekah, armuzna, dan lokasi lainnya, dan kendaraan operasional memiliki stiker yang dapat digunakan pada musim haji. 2. Penyediaan Tenaga Ahli/ Muthawwif dengan kriteria sebanyak 1 orang, bersedia bertugas ealam operasional posko petugas haji DKI Jakarta,  Bersedia bertugas selama operasional posko petugas haji DKI Jakarta, Berkewarganegaran Indonesia, Memahami penyelenggaraan Ibadah Haji secara syariah dan teknis operasional, Mampu berbahasa Arab dan Indonesia. Memiliki izin tinggal (resident identity) dan SIM di Arab Saudi yang masih berlaku, Berpengalaman minimal 4 (empat) tahun, Memahami lokasi pemondokan jemaah haji Indonesia Kantor Daker/Kantor Kesehatan Haji/Rumah Sakit/Sektor/PPIH Arab Saudi, dan Memiliki izin kerja di luar negeri yang masih berlaku. 3. Penyediaan makanan dan minuman rapat untuk petugas haji, serta makanan dan minuman harian petugas piket posko meliputi : Mampu menyediakan konsumsi dalam bentuk fullboard di hotel/posko, Mampu menyediakan konsumsi untuk petugas piket posko 7 orang per hari, dan Mampu menyediakan konsumsi untuk rapat koordinasi petugas haji. 4. Penyewaan kamar hotel di Kota Mekkah untuk dijadikan Posko Petugas Haji sebagai pusat koordinasi dan konsolidasi petugas haji Provinsi DKI Jakarta dengan spesifikasi : Hotel setara Bintang ***** 5 (lima), Minimal 2 (dua) buah kamar tidur dengan 5 (tiga) bed, 1 (satu) ruang rapat atau prefunction room dengan kapasitas minimal 30 orang, Tersedia area parkir untuk kendaraan operasional/stand by saat dibutuhkan, Berlokasi area ring 1 (satu) Masjidil Haram, tersedia 1 orang petugas posko, Memiliki dapur bersih, Mampu menyediakan buah-buahan, air mineral, gula, kopi, teh, susu beserta peralatannya.', 1128500000, 'absurd', 'Spesifikasi menunjukkan fasilitas sangat mewah dan berpotensi tidak proporsional untuk tugas fasilitasi petugas, terutama permintaan hotel setara bintang 5 di ring 1 Masjidil Haram serta kendaraan operasional minimal 4000 CC. Indikasi ini kuat menimbulkan kesan penggunaan APBD yang berlebihan dan tidak hemat.', NULL, NULL, 4, 1, 1, 1, 1, 328017);
